<script setup>
import UiSelect from './ui/select/Select.vue'
import {Button as UiButton} from './ui/button'
import {DatePicker,DateRangePicker} from './ui/date-picker'
import {useScope} from '../store'
// Company / farm / block / plot / cycle / date filters above every /lotus screen. Emits change after scope is edited.
defineProps({page:String,busy:Boolean,options:{type:Object,required:true},companies:{type:Array,required:true},farms:{type:Array,required:true}})
defineEmits(['change','refresh'])
const scope=useScope()
</script>
<template><div class="scope-picker"><label v-if="companies.length>1">Công ty<UiSelect v-model="scope.company" @change="scope.clearBelow('company');$emit('change')"><option value="">Tất cả công ty</option><option v-for="c in companies" :key="c">{{c}}</option></UiSelect></label><label>Vườn<UiSelect v-model="scope.farm" @change="scope.clearBelow('farm');$emit('change')"><option value="">Tất cả vườn</option><option v-for="f in farms" :key="f.name" :value="f.name">{{f.farm_name||f.name}}</option></UiSelect></label><label v-if="options.blocks?.length">Lô<UiSelect v-model="scope.block" @change="scope.clearBelow('block');$emit('change')"><option value="">Tất cả lô</option><option v-for="b in options.blocks" :key="b.name" :value="b.name">{{b.block_name||b.name}}</option></UiSelect></label><label v-if="!['forecast','plan-norm'].includes(page)&&options.plots?.length">Thửa<UiSelect v-model="scope.plot" @change="scope.clearBelow('plot');$emit('change')"><option value="">Tất cả thửa</option><option v-for="p in options.plots" :key="p.name" :value="p.name">{{p.plot_name||p.name}}</option></UiSelect></label><label v-if="!['forecast','plan-norm'].includes(page)&&options.cycles?.length">Vụ<UiSelect v-model="scope.cycle" @change="$emit('change')"><option value="">Tất cả vụ</option><option v-for="c in options.cycles" :key="c.name" :value="c.name">{{c.name}} · {{c.cycle_no}}</option></UiSelect></label><label>{{page==='forecast'?'Bắt đầu kế hoạch':'Ngày'}}<DatePicker v-model="scope.date" :label="page==='forecast'?'Bắt đầu kế hoạch':'Ngày'" :clearable="false" @change="scope.from_date='';scope.to_date='';$emit('change')" /></label><label v-if="!['map','trace','admin/settings','forecast'].includes(page)">Từ ngày – đến ngày<DateRangePicker v-model:from="scope.from_date" v-model:to="scope.to_date" label="Từ ngày – đến ngày" @change="$emit('change')" /></label><UiButton variant="outline" :loading="busy" @click="$emit('refresh')">Cập nhật</UiButton></div></template>
